CREATE TABLE IF NOT EXISTS drafts (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(64) NOT NULL, repo VARCHAR(80) NOT NULL, task VARCHAR(30) NOT NULL, content TEXT NOT NULL, status VARCHAR(20) NOT NULL, latency_ms BIGINT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS approved_docs (id VARCHAR(36) PRIMARY KEY, owner_id VARCHAR(64) NOT NULL, repo VARCHAR(80) NOT NULL, path VARCHAR(240) NOT NULL, digest VARCHAR(64) NOT NULL, UNIQUE(owner_id,repo,path));
